import { useEffect, useRef } from "react"

const INTERACTIVE =
  'a, button, [role="button"], [role="tab"], [role="option"], label, summary'
const TEXT_FIELD = 'input, textarea, select, [contenteditable="true"]'
const ENABLED_QUERY =
  "(hover: hover) and (pointer: fine) and (forced-colors: none) and (prefers-reduced-motion: no-preference)"
const RING_EASE = 0.2

type CursorState = "default" | "hover" | "text"

/**
 * Decorative dot and trailing ring over the native pointer, which stays
 * visible. Active only while ENABLED_QUERY matches. Positions go straight to
 * the DOM, not through React state, so pointer moves never re-render.
 */
export const CustomCursor = () => {
  const dotRef = useRef<HTMLDivElement>(null)
  const ringRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const dot = dotRef.current
    const ring = ringRef.current
    if (!dot || !ring) return
    if (!window.matchMedia(ENABLED_QUERY).matches) return

    const root = document.documentElement
    const pointer = { x: -100, y: -100 }
    const ringPos = { x: -100, y: -100 }
    let frame = 0

    const setAttr = (name: string, value: string) => {
      dot.setAttribute(name, value)
      ring.setAttribute(name, value)
    }

    const stateFor = (el: Element | null): CursorState =>
      el?.closest(TEXT_FIELD)
        ? "text"
        : el?.closest(INTERACTIVE)
          ? "hover"
          : "default"

    const followRing = () => {
      ringPos.x += (pointer.x - ringPos.x) * RING_EASE
      ringPos.y += (pointer.y - ringPos.y) * RING_EASE
      ring.style.transform = `translate3d(${ringPos.x}px, ${ringPos.y}px, 0)`
      const settled =
        Math.abs(pointer.x - ringPos.x) < 0.1 &&
        Math.abs(pointer.y - ringPos.y) < 0.1
      frame = settled ? 0 : requestAnimationFrame(followRing)
    }

    const onPointerMove = (event: PointerEvent) => {
      if (event.pointerType === "touch") return
      pointer.x = event.clientX
      pointer.y = event.clientY
      dot.style.transform = `translate3d(${pointer.x}px, ${pointer.y}px, 0)`
      // Start the ring at the pointer when it (re)appears instead of easing in
      // from wherever it was last.
      if (dot.dataset.visible !== "true") {
        ringPos.x = pointer.x
        ringPos.y = pointer.y
      }
      setAttr("data-visible", "true")
      setAttr(
        "data-state",
        stateFor(event.target instanceof Element ? event.target : null)
      )
      if (!frame) frame = requestAnimationFrame(followRing)
    }

    // Scrolling moves content under a still pointer, so re-check what it is over.
    const onScroll = () =>
      setAttr(
        "data-state",
        stateFor(document.elementFromPoint(pointer.x, pointer.y))
      )
    const onPointerDown = () => setAttr("data-pressed", "true")
    const onPointerUp = () => setAttr("data-pressed", "false")
    const onLeave = () => setAttr("data-visible", "false")

    document.addEventListener("pointermove", onPointerMove, { passive: true })
    document.addEventListener("pointerdown", onPointerDown, { passive: true })
    document.addEventListener("pointerup", onPointerUp, { passive: true })
    document.addEventListener("pointercancel", onPointerUp, { passive: true })
    window.addEventListener("scroll", onScroll, { passive: true })
    root.addEventListener("mouseleave", onLeave)

    return () => {
      document.removeEventListener("pointermove", onPointerMove)
      document.removeEventListener("pointerdown", onPointerDown)
      document.removeEventListener("pointerup", onPointerUp)
      document.removeEventListener("pointercancel", onPointerUp)
      window.removeEventListener("scroll", onScroll)
      root.removeEventListener("mouseleave", onLeave)
      cancelAnimationFrame(frame)
    }
  }, [])

  return (
    <>
      <div
        ref={ringRef}
        aria-hidden="true"
        data-visible="false"
        className="custom-cursor group pointer-events-none fixed left-0 top-0 z-[70] opacity-0 transition-opacity duration-200 data-[visible=true]:opacity-100 print:hidden"
      >
        <div className="transition-transform duration-150 ease-out group-data-[pressed=true]:scale-90 motion-reduce:transition-none">
          <div className="size-8 -translate-x-1/2 -translate-y-1/2 rounded-full border border-accent/50 transition-[scale,background-color,border-color,opacity] duration-200 ease-out group-data-[state=hover]:scale-150 group-data-[state=hover]:border-accent group-data-[state=hover]:bg-accent/10 group-data-[state=text]:opacity-0 motion-reduce:transition-none" />
        </div>
      </div>
      <div
        ref={dotRef}
        aria-hidden="true"
        data-visible="false"
        className="custom-cursor group pointer-events-none fixed left-0 top-0 z-[70] opacity-0 transition-opacity duration-200 data-[visible=true]:opacity-100 print:hidden"
      >
        <div className="size-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-accent transition-[scale,opacity] duration-150 group-data-[state=hover]:scale-0 group-data-[state=text]:opacity-0 motion-reduce:transition-none" />
      </div>
    </>
  )
}
