import {
  Component,
  lazy,
  Suspense,
  useEffect,
  useState,
  type ReactNode,
} from "react"
import { Search } from "lucide-react"

// Loaded on first open so the palette adds nothing to the initial bundle.
// lazy() caches a rejected import, so each retry needs a fresh wrapper.
const loadCommandPalette = () =>
  lazy(() =>
    import("@/components/command-palette").then((m) => ({
      default: m.CommandPalette,
    }))
  )

interface PaletteErrorBoundaryProps {
  onError: () => void
  children: ReactNode
}

class PaletteErrorBoundary extends Component<
  PaletteErrorBoundaryProps,
  { failed: boolean }
> {
  state = { failed: false }

  static getDerivedStateFromError() {
    return { failed: true }
  }

  componentDidCatch() {
    this.props.onError()
  }

  render() {
    return this.state.failed ? null : this.props.children
  }
}

export const CommandMenu = () => {
  const [open, setOpen] = useState(false)
  const [loaded, setLoaded] = useState(false)
  const [CommandPalette, setCommandPalette] = useState(loadCommandPalette)

  const resetAfterLoadError = () => {
    setOpen(false)
    setLoaded(false)
    setCommandPalette(loadCommandPalette())
  }

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault()
        setLoaded(true)
        setOpen((isOpen) => !isOpen)
      }
    }
    window.addEventListener("keydown", onKeyDown)
    return () => window.removeEventListener("keydown", onKeyDown)
  }, [])

  return (
    <>
      <button
        type="button"
        onClick={() => {
          setLoaded(true)
          setOpen(true)
        }}
        aria-label="Open command menu (⌘K)"
        aria-haspopup="dialog"
        aria-keyshortcuts="Meta+K Control+K"
        className="inline-flex h-10 min-w-10 cursor-pointer items-center justify-center gap-2 rounded-full px-2.5 text-ink-muted transition-colors hover:bg-ink/5 hover:text-ink sm:border sm:border-line sm:px-3"
      >
        <Search aria-hidden="true" strokeWidth={2} className="size-4" />
        <kbd className="hidden font-sans text-xs pointer-fine:sm:inline">
          ⌘K
        </kbd>
      </button>
      {loaded && (
        <PaletteErrorBoundary onError={resetAfterLoadError}>
          <Suspense fallback={null}>
            <CommandPalette open={open} onClose={() => setOpen(false)} />
          </Suspense>
        </PaletteErrorBoundary>
      )}
    </>
  )
}
