import { seoConfig } from "@/config/seo"
import { socials } from "@/components/social-icons"

interface SeoProps {
  title?: string
  pathname?: string
  noindex?: boolean
}

const {
  siteUrl,
  siteName,
  defaultTitle,
  titleTemplate,
  description,
  language,
  locale,
  twitterHandle,
  googleSiteVerification,
  image,
  person,
} = seoConfig

const homeUrl = `${siteUrl}/`
const imageUrl = `${siteUrl}${image.path}`
const country = { "@type": "Country", name: person.homeCountry }

const jsonLd = {
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebSite",
      "@id": `${homeUrl}#website`,
      name: siteName,
      url: homeUrl,
      inLanguage: language,
      publisher: { "@id": `${homeUrl}#person` },
    },
    {
      "@type": "ProfilePage",
      "@id": `${homeUrl}#profilepage`,
      url: homeUrl,
      name: defaultTitle,
      inLanguage: language,
      isPartOf: { "@id": `${homeUrl}#website` },
      mainEntity: { "@id": `${homeUrl}#person` },
    },
    {
      "@type": "Person",
      "@id": `${homeUrl}#person`,
      name: person.name,
      alternateName: person.alternateName,
      url: homeUrl,
      image: `${siteUrl}${person.image}`,
      jobTitle: person.jobTitle,
      description,
      worksFor: { "@type": "Organization", name: person.worksFor },
      homeLocation: country,
      nationality: country,
      knowsAbout: person.knowsAbout,
      sameAs: socials.map((s) => s.href),
    },
  ],
}

/**
 * Renders document <head> tags via Gatsby's Head API from `seoConfig`.
 * Use from a page: `export const Head: HeadFC = ({ location }) => <Seo pathname={location.pathname} />`
 */
export const Seo = ({ title, pathname = "", noindex = false }: SeoProps) => {
  const pageTitle = title ? titleTemplate(title) : defaultTitle
  const url = `${siteUrl}${pathname}`

  return (
    <>
      <title>{pageTitle}</title>
      <meta name="description" content={description} />
      <meta name="google-site-verification" content={googleSiteVerification} />
      {noindex ? (
        <meta name="robots" content="noindex" />
      ) : (
        <link rel="canonical" href={url} />
      )}

      <meta property="og:type" content="website" />
      <meta property="og:site_name" content={siteName} />
      <meta property="og:locale" content={locale} />
      <meta property="og:title" content={pageTitle} />
      <meta property="og:description" content={description} />
      <meta property="og:image" content={imageUrl} />
      <meta property="og:image:type" content={image.type} />
      <meta property="og:image:width" content={String(image.width)} />
      <meta property="og:image:height" content={String(image.height)} />
      <meta property="og:image:alt" content={image.alt} />
      {!noindex && <meta property="og:url" content={url} />}

      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:site" content={twitterHandle} />
      <meta name="twitter:creator" content={twitterHandle} />
      <meta name="twitter:title" content={pageTitle} />
      <meta name="twitter:description" content={description} />
      <meta name="twitter:image" content={imageUrl} />
      <meta name="twitter:image:alt" content={image.alt} />

      {!noindex && (
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
        />
      )}
    </>
  )
}
