import { useEffect, useRef, useState } from "react"
import { Menu, Moon, Sun, X } from "lucide-react"
import { CommandMenu } from "@/components/command-menu"
import { toggleTheme } from "@/lib/theme"

const links = [
  { id: "about", label: "About" },
  { id: "experience", label: "Experience" },
  { id: "products", label: "Products" },
  { id: "skills", label: "Skills" },
  { id: "contact", label: "Contact" },
]

// Width at which the desktop links replace the menu; matches the `md:` classes.
const DESKTOP_QUERY = "(min-width: 48rem)"

interface NavbarProps {
  isHome: boolean
}

export const Navbar = ({ isHome }: NavbarProps) => {
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState("")
  const menuRef = useRef<HTMLDivElement>(null)
  const toggleRef = useRef<HTMLButtonElement>(null)

  // A bare fragment is a same-document jump that keeps the query string
  // (?utm=…); "/#id" from the home page would drop it and reload the page.
  const sectionHref = (id: string) => (isHome ? `#${id}` : `/#${id}`)

  // Scroll-spy: every section is observed so one without a nav link (the hero,
  // "Beyond the code") clears the highlight instead of leaving a stale one. At
  // the bottom of the page the last link wins: on tall screens the final
  // section never reaches the observed band.
  useEffect(() => {
    const linkIds = new Set(links.map((l) => l.id))
    const lastId = links[links.length - 1].id
    const sections = document.querySelectorAll<HTMLElement>("main section[id]")
    let inBand = ""

    const sync = () => {
      const atBottom =
        window.innerHeight + window.scrollY >=
        document.documentElement.scrollHeight - 2
      setActive(atBottom ? lastId : inBand)
    }

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const { id } = entry.target
            inBand = linkIds.has(id) ? id : ""
          }
        })
        sync()
      },
      { rootMargin: "-45% 0px -50% 0px" }
    )

    sections.forEach((el) => observer.observe(el))
    window.addEventListener("scroll", sync, { passive: true })
    return () => {
      observer.disconnect()
      window.removeEventListener("scroll", sync)
    }
  }, [])

  useEffect(() => {
    if (!open) return
    const close = () => setOpen(false)
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return
      close()
      toggleRef.current?.focus()
    }
    // Any tap or focus outside the menu and its toggle closes it, including
    // opening the ⌘K palette.
    const onOutside = (event: Event) => {
      const target = event.target as Node
      if (
        !menuRef.current?.contains(target) &&
        !toggleRef.current?.contains(target)
      ) {
        close()
      }
    }
    const desktop = window.matchMedia(DESKTOP_QUERY)

    document.addEventListener("keydown", onKeyDown)
    document.addEventListener("pointerdown", onOutside)
    document.addEventListener("focusin", onOutside)
    window.addEventListener("hashchange", close)
    desktop.addEventListener("change", close)
    return () => {
      document.removeEventListener("keydown", onKeyDown)
      document.removeEventListener("pointerdown", onOutside)
      document.removeEventListener("focusin", onOutside)
      window.removeEventListener("hashchange", close)
      desktop.removeEventListener("change", close)
    }
  }, [open])

  const closeMenu = () => setOpen(false)

  const linkClass = (id: string) =>
    `text-sm font-medium transition-colors ${
      active === id
        ? "bg-ink/[0.06] text-ink forced-colors:underline"
        : "text-ink-muted hover:text-ink"
    }`

  return (
    <nav aria-label="Primary" className="mx-auto max-w-6xl px-3 pt-3">
      <div className="pointer-events-auto flex h-14 items-center justify-between rounded-full border border-line bg-surface/70 px-2 shadow-lg shadow-black/20 backdrop-blur-md">
        <a
          href={sectionHref("top")}
          onClick={closeMenu}
          className="flex items-center gap-2.5 rounded-full py-1 pr-3 font-semibold tracking-tight text-ink"
        >
          <span
            aria-hidden="true"
            className="flex size-9 items-center justify-center rounded-full bg-linear-to-br from-primary to-emerald-400 text-sm font-bold text-slate-950"
          >
            SA
          </span>
          Sabuj Ali
        </a>

        <div className="flex items-center gap-1">
          <div className="hidden items-center gap-1 pr-1 md:flex">
            {links.map(({ id, label }) => (
              <a
                key={id}
                href={sectionHref(id)}
                aria-current={active === id ? "location" : undefined}
                className={`relative rounded-full px-3 py-2 before:absolute before:inset-x-0 before:-inset-y-1 ${linkClass(id)}`}
              >
                {label}
              </a>
            ))}
          </div>

          <CommandMenu />

          <button
            type="button"
            onClick={toggleTheme}
            aria-label="Toggle light and dark theme"
            className="inline-flex size-10 cursor-pointer items-center justify-center rounded-full text-ink-muted transition-colors hover:bg-ink/5 hover:text-ink"
          >
            {/* Both icons ship in the static HTML and CSS picks one from
                data-theme, so the right icon shows before hydration. */}
            <Sun
              aria-hidden="true"
              strokeWidth={2}
              className="size-5 in-data-[theme=light]:hidden"
            />
            <Moon
              aria-hidden="true"
              strokeWidth={2}
              className="hidden size-5 in-data-[theme=light]:block"
            />
          </button>

          <button
            ref={toggleRef}
            type="button"
            onClick={() => setOpen((isOpen) => !isOpen)}
            aria-label="Toggle menu"
            aria-expanded={open}
            aria-controls="mobile-menu"
            className="inline-flex size-10 cursor-pointer items-center justify-center rounded-full text-ink-soft transition-colors hover:bg-ink/5 md:hidden"
          >
            {open ? (
              <X aria-hidden="true" strokeWidth={2} className="size-6" />
            ) : (
              <Menu aria-hidden="true" strokeWidth={2} className="size-6" />
            )}
          </button>
        </div>
      </div>

      <div
        ref={menuRef}
        id="mobile-menu"
        hidden={!open}
        className="pointer-events-auto mt-2 flex max-h-[calc(100dvh-5rem)] flex-col gap-1 overflow-y-auto overscroll-contain rounded-2xl border border-line bg-surface/90 p-2 shadow-lg shadow-black/30 backdrop-blur-md md:hidden"
      >
        {links.map(({ id, label }) => (
          <a
            key={id}
            href={sectionHref(id)}
            onClick={closeMenu}
            aria-current={active === id ? "location" : undefined}
            className={`rounded-xl px-4 py-3 ${linkClass(id)}`}
          >
            {label}
          </a>
        ))}
      </div>
    </nav>
  )
}
