import type React from "react"
import { Navbar } from "@/components/layout/navbar"
import { Footer } from "@/components/layout/footer"
import { CustomCursor } from "@/components/custom-cursor"
import { SpotlightEffect } from "@/components/spotlight-effect"

interface LayoutProps {
  children: React.ReactNode
  /** Set on the page that renders the sections the navbar links to. */
  isHome?: boolean
}

export const Layout = ({ children, isHome = false }: LayoutProps) => (
  <div className="flex min-h-dvh flex-col">
    <a
      href="#main"
      className="sr-only focus:not-sr-only focus:fixed focus:left-4 focus:top-4 focus:z-50 focus:rounded-full focus:bg-primary focus:px-5 focus:py-2.5 focus:font-semibold focus:text-slate-950"
    >
      Skip to content
    </a>
    {/* Only the nav pill and menu take pointer input (the ⌘K dialog inherits
        it from the pill it renders in), so the transparent margins around them
        never block taps on the content scrolling below. */}
    <header className="pointer-events-none sticky top-0 z-30 print:hidden">
      <Navbar isHome={isHome} />
    </header>
    <main id="main" className="flex-1">
      {children}
    </main>
    <Footer />
    <SpotlightEffect />
    <CustomCursor />
  </div>
)
